-- ============================================================================
-- NIS2 70-Backbone — ersetzt den aufgeblähten 237er-NIS2-Katalog durch die
-- 70 Checks der NIS2-Checkliste (RL (EU) 2022/2555 + DVO 2024/2690).
-- Erzeugt aus NIS2_70_MAPPING_SPEC.md. Idempotent.
--   * UPSERT: vorhandene (wiederverwendete) Kontrollen behalten ihre risiko_ids
--     (meta = alt || neu); iso_ids/coverage/badge/legal_ref werden aktualisiert.
--   * TRIM: NIS2-Kontrollen außerhalb der 70 werden entfernt (Cascade räumt
--     control_node_member/control_iso mit auf). Nur Demo-Daten betroffen.
--   * BSI-Mapping ist indirekt über gemeinsame iso_ids (BSI-Kontrollen tragen
--     dieselben ISO-Refs); bsi_ids in meta sind zusätzlich als Referenz gesetzt.
-- ============================================================================
BEGIN;

-- 1) UPSERT der 70 Rückgrat-Kontrollen (risiko_ids bleiben via meta-Merge erhalten)
INSERT INTO public.controls (framework, id, req_de, req_en, meta) VALUES
  ('NIS2', 'scope-01', 'Wurde jede juristische Person der Gruppe einzeln anhand der Sektorlisten (Annex I/II zuerst, Größe zweitens) auf Anwendbarkeit geprüft?', 'Has every legal entity in the group been tested separately against the Annex I/II sector lists first and the size threshold second?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 2(1); Annexes I–II", "section": "A-Scope", "check_nr": 1}'::jsonb),
  ('NIS2', 'scope-02', 'Wurde der Größentest anhand der Kommissionsempfehlung 2003/361/EC (mittleres Unternehmen als Auslöser) durchgeführt, nicht per Faustregel?', 'Was the size test applied against Commission Recommendation 2003/361/EC (medium-sized enterprise as trigger) rather than a rule of thumb?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 2(1); Rec. 2003/361/EC", "section": "A-Scope", "check_nr": 2}'::jsonb),
  ('NIS2', 'scope-03', 'Wurden Beschäftigten- und Finanzzahlen inkl. Partner- (pro rata) und verbundener Unternehmen (voll) berechnet, nicht nur der Einzelentity?', 'Were headcount and financial figures calculated including partner (pro rata) and linked (full) enterprises, not the standalone entity?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Rec. 2003/361/EC Art. 3, 6", "section": "A-Scope", "check_nr": 3}'::jsonb),
  ('NIS2', 'reg-02', 'Ist für jede Entity im Anwendungsbereich die Klasse (essential/important) nach Art. 3 dokumentiert?', 'Is the class (essential/important) per Article 3 recorded for each in-scope entity?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 3(1)–(2)", "section": "A-Scope", "check_nr": 4}'::jsonb),
  ('NIS2', 'scope-05', 'Wurden die größenunabhängigen Typen (TK-Anbieter, Vertrauensdienste, TLD/DNS, kritische Einrichtungen nach RL 2022/2557, Domain-Registrierungsdienste) separat identifiziert?', 'Were the size-independent types (electronic-comms, trust-service, TLD/DNS, CER entities, domain-registration providers) identified separately?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 2(2)(a),(3),(4)", "section": "A-Scope", "check_nr": 5}'::jsonb),
  ('NIS2', 'scope-06', 'Wurden die größenunabhängigen Gründe (Alleinanbieter, öffentliche Sicherheit, systemisches Risiko, nationale/regionale Kritikalität, Zentralverwaltung) bewertet und das Ergebnis festgehalten?', 'Were the size-independent grounds (sole provider, public safety, systemic risk, criticality, central-government) assessed and the result recorded?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 2(2)(b)–(f)", "section": "A-Scope", "check_nr": 6}'::jsonb),
  ('NIS2', 'scope-07', 'Wurden die Ausnahmen (nationale Sicherheit/Verteidigung/Strafverfolgung 2(7)–(8), Vertrauensdienst 2(9), DORA-Ausnahme 2(10), Geheimhaltung 2(11)) je Provision geprüft?', 'Were the exclusions (national security/defence/law enforcement 2(7)–(8), trust-service 2(9), DORA 2(10), secrecy 2(11)) checked per provision?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 2(7)–(11)", "section": "A-Scope", "check_nr": 7}'::jsonb),
  ('NIS2', 'scope-08', 'Wurde bei sektorspezifischem Unionsrecht mindestens gleichwertiger Wirkung (z. B. DORA) geprüft, ob Art. 21, Art. 23 oder beide verdrängt sind?', 'Where sector-specific Union law of at least equivalent effect applies (e.g. DORA), was it assessed whether Article 21, 23 or both are displaced?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 4(1)–(2)", "section": "A-Scope", "check_nr": 8}'::jsonb),
  ('NIS2', 'scope-09', 'Wurde der zuständige Mitgliedstaat nach der korrekten Regel des Art. 26(1) bestimmt?', 'Was the competent Member State determined by the correct Article 26(1) rule?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 26(1)(a)–(c)", "section": "A-Scope", "check_nr": 9}'::jsonb),
  ('NIS2', 'scope-10', 'Wurde für die Digitalanbieter-Typen die Hauptniederlassung nach dem Test des Art. 26(2) bestimmt?', 'For the digital-provider types, was the main establishment determined by the Article 26(2) test?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 26(2)", "section": "A-Scope", "check_nr": 10}'::jsonb),
  ('NIS2', 'scope-11', 'Hat eine nicht in der Union niedergelassene Entity der Art.-26(1)(b)-Typen einen Vertreter in einem Mitgliedstaat benannt, in dem sie Dienste anbietet?', 'Has a non-EU entity of the Article 26(1)(b) types designated a representative in a Member State where it offers services?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 26(3)", "section": "A-Scope", "check_nr": 11}'::jsonb),
  ('NIS2', 'scope-12', 'Wird der Anwendungsbereich bei geänderten Fakten (Merger, Schwellenüberschreitung, neuer/eingestellter Dienst) neu bewertet, nicht nur einmalig zu Beginn?', 'Is scope reassessed when facts change (merger, threshold crossing, new/discontinued service), not only once at the start?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "H", "legal_ref": "Praxis; vgl. Art. 3(4)", "section": "A-Scope", "check_nr": 12}'::jsonb),
  ('NIS2', 'scope-13', 'Wird das Ergebnis der Scope-Bewertung datiert, unterschrieben und aufbewahrt — auch für als „out of scope" bewertete Entities mit Begründung?', 'Is the scope-assessment result dated, signed and kept — including for out-of-scope entities with the reason?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "H", "legal_ref": "Evidenzpraxis", "section": "A-Scope", "check_nr": 13}'::jsonb),
  ('NIS2', 'reg-01', 'Hat die Entity mindestens Name, Anschrift, aktuelle Kontaktdaten (E-Mail, IP-Bereiche, Telefon), Sektor/Subsektor und die betroffenen Mitgliedstaaten an die Behörde übermittelt?', 'Has the entity submitted at least name, address, up-to-date contacts (email, IP ranges, phone), sector/subsector and the Member States concerned to the authority?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 3(4)", "section": "Registry", "check_nr": 14}'::jsonb),
  ('NIS2', 'reg-15', 'Meldet ein Prozess jede Änderung dieser Registrierungsdaten unverzüglich, spätestens binnen zwei Wochen?', 'Does a process report any change to the registration data without delay and within two weeks?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 3(4)", "section": "Registry", "check_nr": 15}'::jsonb),
  ('NIS2', 'reg-16', 'Ist festgehalten, dass die Liste essential/important eine Behördenpflicht ist und das Gelistetsein (oder Fehlen) die Pflichten nicht auslöst — der Scope folgt aus Art. 2 und 3?', 'Is it recorded that the essential/important list is an authority duty and that being on it (or absent) does not trigger the obligations — scope follows from Articles 2 and 3?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "H", "legal_ref": "Lesart Art. 2, 3(3)", "section": "Registry", "check_nr": 16}'::jsonb),
  ('NIS2', 'reg-17', 'Haben Entities der Art.-27-Typen die Zusatz-Registrierungsdaten (Anschrift der Haupt- und weiterer Niederlassungen in der Union bzw. des Vertreters) übermittelt?', 'Have entities of the Article 27 types submitted the additional registry data (address of main and other EU establishments or of the representative)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 27(2)", "section": "Registry", "check_nr": 17}'::jsonb),
  ('NIS2', 'reg-18', 'Werden Änderungen der Art.-27-Registrierungsdaten unverzüglich, spätestens binnen drei Monaten gemeldet?', 'Are changes to the Article 27 registry data notified without delay and within three months?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 27(3)", "section": "Registry", "check_nr": 18}'::jsonb),
  ('NIS2', 'reg-19', 'Führen TLD-Registries und Domain-Registrierungsdienste korrekte Registrierungsdaten in einer eigenen Datenbank, veröffentlichen die nicht-personenbezogenen Daten und beantworten Zugriffsanfragen binnen 72 Stunden?', 'Do TLD registries and domain-registration providers keep accurate data in a dedicated database, publish non-personal data, and answer access requests within 72 hours?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 28(1)–(5)", "section": "Registry", "check_nr": 19}'::jsonb),
  ('NIS2', 'reg-20', 'Halten benannte Personen und Stellvertreter getestete (nicht nur angelegte) Zugangsdaten für den Registrierungs- und Meldekanal?', 'Do named persons and deputies hold tested (not merely created) credentials for the registration and reporting channel?', '{"coverage": "teilw", "iso_ids": ["a5-97"], "bsi_ids": ["GC.7.1.2"], "badge": "H", "legal_ref": "Operative Praxis", "section": "Registry", "check_nr": 20}'::jsonb),
  ('NIS2', 'nis2-gov-05', 'Hat das Leitungsorgan die Cybersicherheits-Risikomanagementmaßnahmen förmlich (datierter Beschluss, keine Präsentation) gebilligt?', 'Has the management body formally approved the cybersecurity risk-management measures as a dated decision, not a presentation?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 20(1)", "section": "Governance", "check_nr": 21}'::jsonb),
  ('NIS2', 'gov-03', 'Übt das Leitungsorgan die Überwachung der Umsetzung nachweislich aus (stehender TOP, Protokolle, Berichtslinie bis zur Spitze)?', 'Does the management body demonstrably exercise oversight of implementation (standing agenda item, minutes, reporting line to the top)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 20(1)", "section": "Governance", "check_nr": 22}'::jsonb),
  ('NIS2', 'nis2-gov-06', 'Ist festgehalten, dass Mitglieder des Leitungsorgans für Art.-21-Verstöße haftbar sein können und wie diese Haftung im nationalen und Gesellschaftsrecht ausgestaltet ist?', 'Is it recorded that management-body members can be liable for Article 21 infringements and how that liability is framed in national and company law?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 20(1)", "section": "Governance", "check_nr": 23}'::jsonb),
  ('NIS2', 'gov-01', 'Haben die Mitglieder des Leitungsorgans eine Schulung mit belegter Teilnahme absolviert, die ausreichende Kenntnisse zur Risikoerkennung und -bewertung vermittelt?', 'Have management-body members completed evidenced training giving sufficient knowledge to identify and assess risks?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 20(2)", "section": "Governance", "check_nr": 24}'::jsonb),
  ('NIS2', 'a-12', 'Erhalten auch die Beschäftigten Cybersicherheits- und Cyberhygiene-Schulungen (Pflichtmaßnahme nach Art. 21(2)(g))?', 'Do employees also receive cybersecurity and cyber-hygiene training (a mandatory measure under Article 21(2)(g))?', '{"coverage": "voll", "iso_ids": ["a6-08"], "bsi_ids": ["PERS.4.2"], "badge": "R", "legal_ref": "Art. 21(2)(g); Art. 20(2)", "section": "Governance", "check_nr": 25}'::jsonb),
  ('NIS2', 'gov-04', 'Dokumentiert das Leitungsorgan die Aufgabendelegation samt der Feststellung, dass die Delegation die letztliche Verantwortung nicht verschiebt?', 'Does the management body document the delegation of tasks together with the record that delegation does not move ultimate responsibility?', '{"coverage": "teilw", "iso_ids": ["c5-09"], "bsi_ids": ["GC.8.1.1"], "badge": "H", "legal_ref": "Gesellschaftsrechtliche Praxis", "section": "Governance", "check_nr": 26}'::jsonb),
  ('NIS2', 'art21-27', 'Sind die Maßnahmen als angemessen und verhältnismäßig dokumentiert (All-Hazards, Stand der Technik/Standards, Kosten, Größe, Risikoexposition, Eintritts-/Schwerewahrscheinlichkeit), lesbar für einen Prüfer?', 'Are the measures documented as appropriate and proportionate (all-hazards, state of the art/standards, cost, size, exposure, likelihood/severity), readable by an assessor?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 21(1)", "section": "Art21-Measures", "check_nr": 27}'::jsonb),
  ('NIS2', 'a-01', 'Existieren genehmigte und datierte Leitlinien zur Risikoanalyse und Informationssystem-Sicherheit?', 'Do approved and dated policies on risk analysis and information-system security exist?', '{"coverage": "voll", "iso_ids": ["a5-01", "a5-02"], "bsi_ids": ["GC.6.1.3", "GC.6.1.4"], "badge": "R", "legal_ref": "Art. 21(2)(a)", "section": "Art21-Measures", "check_nr": 28}'::jsonb),
  ('NIS2', 'risk-03', 'Ist die Kette von der Risikobewertung zur Entscheidung nachvollziehbar (Risiko → gewählte Behandlung → umgesetzte Maßnahme → Restrisiko durch benannte Person akzeptiert)?', 'Is the chain from risk assessment to decision traceable (risk → treatment → implemented measure → residual risk accepted by a named person)?', '{"coverage": "voll", "iso_ids": ["c6-11", "c8-07"], "bsi_ids": ["RISK.1.3", "UMS.2.1"], "badge": "H", "legal_ref": "Evidenz für Art. 21(2)(a),(f)", "section": "Art21-Measures", "check_nr": 29}'::jsonb),
  ('NIS2', 'b-04', 'Ist die Vorfallbehandlung durchgängig definiert (Erkennung, Klassifizierung, Eskalation, Eindämmung, Wiederherstellung, Lessons Learned)?', 'Is incident handling defined end to end (detection, classification, escalation, containment, recovery, lessons learned)?', '{"coverage": "voll", "iso_ids": ["a5-61"], "bsi_ids": ["REA.2.1", "REA.2.6"], "badge": "R", "legal_ref": "Art. 21(2)(b)", "section": "Art21-Measures", "check_nr": 30}'::jsonb),
  ('NIS2', 'c-01', 'Ist Business Continuity (Backup-Management, Disaster Recovery, Krisenmanagement) eingerichtet?', 'Is business continuity (backup management, disaster recovery, crisis management) in place?', '{"coverage": "voll", "iso_ids": ["a8-46", "a5-74"], "bsi_ids": ["NOT.4.1", "NOT.3.2"], "badge": "R", "legal_ref": "Art. 21(2)(c)", "section": "Art21-Measures", "check_nr": 31}'::jsonb),
  ('NIS2', 'c-04', 'Wurde in den letzten zwölf Monaten eine Wiederherstellung tatsächlich durchgeführt und dokumentiert, und liegen Backups in einer für Angreifer mit Domänenrechten unveränderlichen Form vor?', 'Has a restore actually been performed and recorded within the last twelve months, and are backups held immutable to an attacker with domain rights?', '{"coverage": "voll", "iso_ids": ["a8-137", "a8-48"], "bsi_ids": ["NOT.4.14", "NOT.4.16"], "badge": "H", "legal_ref": "Stand der Technik; Art. 21(2)(c)", "section": "Art21-Measures", "check_nr": 32}'::jsonb),
  ('NIS2', 'd-02', 'Deckt die Lieferkettensicherheit die sicherheitsrelevanten Aspekte der Beziehungen zu direkten Lieferanten und Dienstleistern ab?', 'Does supply-chain security cover the security-related aspects of relationships with direct suppliers and service providers?', '{"coverage": "voll", "iso_ids": ["a5-47"], "bsi_ids": ["BES.1.1"], "badge": "R", "legal_ref": "Art. 21(2)(d)", "section": "Art21-Measures", "check_nr": 33}'::jsonb),
  ('NIS2', 'e-14', 'Ist die Sicherheit in Beschaffung, Entwicklung und Wartung von Netz- und Informationssystemen inkl. Schwachstellenbehandlung und -offenlegung geregelt?', 'Is security in acquisition, development and maintenance of network/information systems incl. vulnerability handling and disclosure regulated?', '{"coverage": "voll", "iso_ids": ["a8-81", "a8-85"], "bsi_ids": ["DEV.2.1", "BES.4.2"], "badge": "R", "legal_ref": "Art. 21(2)(e)", "section": "Art21-Measures", "check_nr": 34}'::jsonb),
  ('NIS2', 'vul-9', 'Ist die Schwachstellenbehandlung operativ (Scan-Kadenz, Patch-Fenster nach Schweregrad, dokumentierte Ausnahmen mit Owner und Enddatum), nicht nur nominal?', 'Is vulnerability handling operational (scan cadence, severity-based patch windows, documented exceptions with owner and end date), not merely nominal?', '{"coverage": "voll", "iso_ids": ["a8-31", "a8-32"], "bsi_ids": ["DET.5.1", "DET.5.10"], "badge": "H", "legal_ref": "Evidenz für Art. 21(2)(e)", "section": "Art21-Measures", "check_nr": 35}'::jsonb),
  ('NIS2', 'f-01', 'Existieren Leitlinien und Verfahren zur Bewertung der Wirksamkeit der Maßnahmen mit schriftlich festgehaltenem Ergebnis?', 'Do policies and procedures to assess the effectiveness of the measures exist, with a written-down result?', '{"coverage": "voll", "iso_ids": ["c9-01"], "bsi_ids": ["PERF.5.1.5", "VRB.6.1"], "badge": "R", "legal_ref": "Art. 21(2)(f)", "section": "Art21-Measures", "check_nr": 36}'::jsonb),
  ('NIS2', 'aw-01', 'Finden grundlegende Cyberhygiene-Praktiken und rollenbasierte Cybersicherheitsschulungen mit belegter Teilnahme und Ergebnissen statt?', 'Are basic cyber-hygiene practices and role-based cybersecurity training with evidenced attendance and results in place?', '{"coverage": "voll", "iso_ids": ["a6-08"], "bsi_ids": ["PERS.4.2"], "badge": "R", "legal_ref": "Art. 21(2)(g)", "section": "Art21-Measures", "check_nr": 37}'::jsonb),
  ('NIS2', 'h-01', 'Existieren Leitlinien und Verfahren zum Einsatz von Kryptografie und, wo angemessen, Verschlüsselung?', 'Do policies and procedures on the use of cryptography and, where appropriate, encryption exist?', '{"coverage": "voll", "iso_ids": ["a8-77"], "bsi_ids": ["BER.7.1"], "badge": "R", "legal_ref": "Art. 21(2)(h)", "section": "Art21-Measures", "check_nr": 38}'::jsonb),
  ('NIS2', 'i-01', 'Sind Personalsicherheit, Zugriffskontroll-Leitlinien und Asset-Management geregelt?', 'Are human-resources security, access-control policies and asset management in place?', '{"coverage": "voll", "iso_ids": ["a6-01", "a5-35", "a5-21"], "bsi_ids": ["PERS.3.6", "BER.5.1", "ASST.2.2"], "badge": "R", "legal_ref": "Art. 21(2)(i)", "section": "Art21-Measures", "check_nr": 39}'::jsonb),
  ('NIS2', 'j-01', 'Sind Multi-Faktor-/kontinuierliche Authentifizierung, gesicherte Sprach-/Video-/Textkommunikation und gesicherte Notfallkommunikation innerhalb der Entity umgesetzt (wo angemessen)?', 'Are MFA/continuous authentication, secured voice/video/text and secured emergency communication within the entity implemented (where appropriate)?', '{"coverage": "voll", "iso_ids": ["a5-103", "a5-95"], "bsi_ids": ["BER.6.4", "NOT.3.5"], "badge": "R", "legal_ref": "Art. 21(2)(j)", "section": "Art21-Measures", "check_nr": 40}'::jsonb),
  ('NIS2', 'a-03', 'Existiert ein vollständiges, klassifiziertes Asset-Inventar mit benannten Ownern und Schutzbedarf, dessen Review-Zyklus tatsächlich gelaufen ist?', 'Does a complete, classified asset inventory with named owners and protection needs exist, whose review cycle has actually run?', '{"coverage": "voll", "iso_ids": ["a5-21", "a5-22"], "bsi_ids": ["ASST.2.2", "ASST.2.1.1"], "badge": "H", "legal_ref": "Evidenz für Art. 21(2)(i)", "section": "Art21-Measures", "check_nr": 41}'::jsonb),
  ('NIS2', 'iam-mfa-1', 'Tragen privilegierte Konten MFA, und werden Zugriffsrechte periodisch mit belegenden Logs rezertifiziert?', 'Do privileged accounts carry MFA, and are access rights recertified periodically with logs proving it?', '{"coverage": "voll", "iso_ids": ["a5-103", "a5-99"], "bsi_ids": ["BER.6.5", "BER.5.3"], "badge": "H", "legal_ref": "Evidenz für Art. 21(2)(i)–(j)", "section": "Art21-Measures", "check_nr": 42}'::jsonb),
  ('NIS2', 'a-10', 'Werden sicherheitsrelevante Logs zentral gesammelt und über einen zur Vorfallrekonstruktion ausreichenden Zeitraum (in Monaten) aufbewahrt?', 'Are security-relevant logs collected centrally and retained for a period (measured in months) sufficient to reconstruct an incident?', '{"coverage": "voll", "iso_ids": ["a8-125", "a8-128"], "bsi_ids": ["DET.3.5"], "badge": "H", "legal_ref": "Evidenz für Art. 21(2)(b); DVO 2024/2690", "section": "Art21-Measures", "check_nr": 43}'::jsonb),
  ('NIS2', 'phy-01', 'Sind physische und umgebungsbezogene Sicherheit sowie die tragenden Versorgungseinrichtungen der Systeme abgedeckt?', 'Are physical and environmental security and the supporting utilities the systems depend on covered?', '{"coverage": "voll", "iso_ids": ["a7-01"], "bsi_ids": ["GEB.2.1"], "badge": "R", "legal_ref": "Art. 21(2), Einleitungssatz", "section": "Art21-Measures", "check_nr": 44}'::jsonb),
  ('NIS2', 'art21-45', 'Werden bei festgestellter Nichteinhaltung der Maßnahmen ohne unangemessene Verzögerung Korrekturmaßnahmen ergriffen und die Feststellung selbst dokumentiert?', 'Where non-compliance with the measures is found, are corrective measures taken without undue delay and the finding itself recorded?', '{"coverage": "teilw", "iso_ids": ["c10-02", "c10-03"], "bsi_ids": ["VRB.2.1", "VRB.4.1"], "badge": "R", "legal_ref": "Art. 21(4)", "section": "Art21-Measures", "check_nr": 45}'::jsonb),
  ('NIS2', 'art21-46', 'Werden bei DVO-2024/2690-Typen sämtliche technischen/methodischen Anforderungen umgesetzt und Nichtanwendungen (where appropriate/applicable) nach Art. 2(2) nachvollziehbar begründet und dokumentiert?', 'For Implementing-Regulation types, is each technical/methodological requirement implemented and any non-application reasoned and documented per Article 2(2)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "D", "legal_ref": "Art. 21(5); DVO 2024/2690 Art. 2(2)", "section": "Art21-Measures", "check_nr": 46}'::jsonb),
  ('NIS2', 'sup-47', 'Wurden die lieferantenspezifischen Schwachstellen, die Gesamtqualität der Produkte und Cybersicherheitspraktiken sowie die sicheren Entwicklungsverfahren jedes direkten Lieferanten berücksichtigt?', 'Were each direct supplier''s specific vulnerabilities, overall product quality, cybersecurity practices and secure development procedures taken into account?', '{"coverage": "teilw", "iso_ids": ["a5-48", "a5-56"], "bsi_ids": ["BES.3.2", "BES.4.8"], "badge": "R", "legal_ref": "Art. 21(3)", "section": "SupplyChain", "check_nr": 47}'::jsonb),
  ('NIS2', 'sup-05', 'Werden die Ergebnisse einer koordinierten EU-Risikobewertung kritischer Lieferketten für die betroffenen Dienste berücksichtigt?', 'Are the results of a Union-level coordinated security risk assessment of critical supply chains taken into account for the services concerned?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 22(1); Art. 21(3)", "section": "SupplyChain", "check_nr": 48}'::jsonb),
  ('NIS2', 'd-01', 'Existiert ein Lieferanteninventar, das Kritikalität, den je Lieferant gehaltenen Zugriff und Konzentrationsrisiken (mehrere kritische Dienste beim selben Provider) erfasst?', 'Does a supplier inventory exist that records criticality, the access each supplier holds, and concentration risk (several critical services with one provider)?', '{"coverage": "teilw", "iso_ids": ["a5-105"], "bsi_ids": ["BES.1.3", "BES.1.3.1"], "badge": "H", "legal_ref": "Evidenz für Art. 21(2)(d),(3)", "section": "SupplyChain", "check_nr": 49}'::jsonb),
  ('NIS2', 'd-04', 'Werden Sicherheitsanforderungen vertraglich weitergegeben (Fragebogen, Service Level, Auditklausel) inkl. einer mit der eigenen 24-Stunden-Frist kompatiblen Meldepflicht?', 'Are security requirements passed down the contracts (questionnaire, SLAs, audit clause) including a notification duty compatible with the entity''s own 24-hour deadline?', '{"coverage": "teilw", "iso_ids": ["a5-51", "a5-110"], "bsi_ids": ["BES.5.11", "BES.5.12"], "badge": "H", "legal_ref": "Praxis unter Art. 21(2)(d)", "section": "SupplyChain", "check_nr": 50}'::jsonb),
  ('NIS2', 'd-05', 'Sind Lieferantenaussagen belegt statt behauptet (Zertifikate, Auditberichte, Testergebnisse liegen datiert vor und wurden gelesen)?', 'Are supplier answers evidenced rather than asserted (certificates, audit reports, test results on file, dated, and read)?', '{"coverage": "voll", "iso_ids": ["a5-56"], "bsi_ids": ["BES.4.8", "BES.4.8.1"], "badge": "H", "legal_ref": "Evidenz für Art. 21(3)", "section": "SupplyChain", "check_nr": 51}'::jsonb),
  ('NIS2', 'nis2-sig-01', 'Ist ein erheblicher Sicherheitsvorfall schriftlich anhand des RL-eigenen Tests definiert, mit benanntem Entscheider und benanntem Stellvertreter?', 'Is a significant incident defined in writing against the Directive''s own test, with a named decision-maker and a named deputy?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(3)", "section": "Reporting", "check_nr": 52}'::jsonb),
  ('NIS2', 'nis2-sig-02', 'Ist festgehalten, dass „geeignet, zu verursachen" genügt (schwere Betriebsstörung/finanzieller Schaden bzw. erheblicher Schaden bei Dritten) und realisierter Schaden nicht erforderlich ist?', 'Is it recorded that „capable of causing" is enough (severe disruption/financial loss or considerable damage to others) and that realised harm is not required?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(3)", "section": "Reporting", "check_nr": 53}'::jsonb),
  ('NIS2', 'nis2-sig-03', 'Entscheiden dort, wo die Kommission Erheblichkeitsschwellen für den Entity-Typ festgelegt hat, diese Schwellen (nicht eine Hausregel), und läuft die 24-Stunden-Uhr ab Kenntnisnahme des erheblichen Vorfalls?', 'Where the Commission has set significance thresholds for the entity type, do those thresholds decide (not a house rule), and does the 24-hour clock run from becoming aware?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "D", "legal_ref": "Art. 23(11); DVO 2024/2690", "section": "Reporting", "check_nr": 54}'::jsonb),
  ('NIS2', 'nis2-sig-04', 'Werden einzeln nicht erhebliche wiederkehrende Vorfälle zusammen bewertet (mind. 2× in 6 Monaten, gleiche mutmaßliche Ursache, gemeinsam über der Schadensschwelle) und als ein erheblicher Vorfall behandelt?', 'Are individually non-significant recurring incidents assessed together (≥2× in 6 months, same apparent root cause, collectively over the loss threshold) as one significant incident?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "D", "legal_ref": "DVO 2024/2690 Art. 4", "section": "Reporting", "check_nr": 55}'::jsonb),
  ('NIS2', 'inc-comm-1', 'Erreicht die Frühwarnung das CSIRT bzw. die zuständige Behörde unverzüglich und in jedem Fall binnen 24 Stunden nach Kenntnisnahme?', 'Does the early warning reach the CSIRT or competent authority without undue delay and in any event within 24 hours of becoming aware?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4)(a)", "section": "Reporting", "check_nr": 56}'::jsonb),
  ('NIS2', 'notif-57', 'Gibt die Frühwarnung an, ob der Vorfall im Verdacht steht, durch rechtswidrige/böswillige Handlungen verursacht zu sein, und ob er grenzüberschreitende Auswirkungen haben könnte?', 'Does the early warning state whether the incident is suspected of unlawful/malicious cause and whether it could have cross-border impact?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4)(a)", "section": "Reporting", "check_nr": 57}'::jsonb),
  ('NIS2', 'inc-comm-2', 'Folgt die Vorfallmeldung binnen 72 Stunden nach Kenntnisnahme und aktualisiert die Frühwarnung mit Erstbewertung (Schwere, Auswirkung, ggf. Kompromittierungsindikatoren)?', 'Does the incident notification follow within 72 hours, updating the early warning with an initial assessment (severity, impact, IoCs where available)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4)(b)", "section": "Reporting", "check_nr": 58}'::jsonb),
  ('NIS2', 'notif-59', 'Wird auf Anfrage des CSIRT/der Behörde ein Zwischenbericht bereitgestellt?', 'Is an intermediate report provided on request from the CSIRT or competent authority?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4)(c)", "section": "Reporting", "check_nr": 59}'::jsonb),
  ('NIS2', 'inc-comm-3', 'Wird der Abschlussbericht spätestens einen Monat nach der Vorfallmeldung eingereicht (detaillierte Beschreibung, Schwere/Auswirkung, Bedrohungstyp/Ursache, angewandte/laufende Minderungsmaßnahmen, grenzüberschreitende Auswirkung)?', 'Is the final report submitted no later than one month after the notification (detailed description, severity/impact, threat type/root cause, mitigations, cross-border impact)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4)(d)", "section": "Reporting", "check_nr": 60}'::jsonb),
  ('NIS2', 'notif-61', 'Tritt bei noch laufendem Vorfall an die Stelle des Abschlussberichts ein Fortschrittsbericht, gefolgt vom Abschlussbericht binnen eines Monats nach Bewältigung?', 'Where the incident is still ongoing, does a progress report take the final report''s place, followed by the final report within one month of the incident being handled?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4)(e)", "section": "Reporting", "check_nr": 61}'::jsonb),
  ('NIS2', 'nis2-notif-01', 'Werden die Dienstempfänger, wo angemessen, über erhebliche Vorfälle mit Auswirkung auf den Dienst sowie über erhebliche Cyberbedrohungen samt möglicher Gegenmaßnahmen informiert?', 'Where appropriate, are service recipients informed of significant incidents affecting the service and of significant cyber threats together with possible remedies?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(1)–(2)", "section": "Reporting", "check_nr": 62}'::jsonb),
  ('NIS2', 'notif-63', 'Halten Vertrauensdiensteanbieter für Vorfälle mit erheblicher Auswirkung auf ihre Vertrauensdienste die auf 24 Stunden verkürzte Meldefrist (statt 72 h) ein?', 'Do trust-service providers meet the 24-hour deadline (instead of 72 h) for incidents with significant impact on their trust services?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 23(4) UAbs. 2", "section": "Reporting", "check_nr": 63}'::jsonb),
  ('NIS2', 'notif-64', 'Werden der Zeitpunkt der Kenntnisnahme und der Absendezeitpunkt jedes Berichts erfasst (Frühwarnung/Meldung ab Kenntnis, Abschluss ab Meldung bzw. ab Bewältigung)?', 'Are the moment of becoming aware and the moment each report was sent recorded (early warning/notification from awareness, final report from notification or from handling)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "H", "legal_ref": "Evidenz für Art. 23(4)", "section": "Reporting", "check_nr": 64}'::jsonb),
  ('NIS2', 'notif-65', 'Wurde der Meldeweg außerhalb der Geschäftszeiten mindestens einmal Ende-zu-Ende geprobt (inkl. Freitagabend)?', 'Has the out-of-hours reporting path been rehearsed end to end at least once (including a Friday evening)?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "H", "legal_ref": "Operative Praxis", "section": "Reporting", "check_nr": 65}'::jsonb),
  ('NIS2', 'supv-66', 'Ist festgehalten, dass essential entities proaktiv beaufsichtigt werden (Vor-Ort-/Ferninspektionen, Audits, Security-Scans, Informations-/Nachweisanforderungen) und important entities ex post?', 'Is it recorded that essential entities are supervised proactively (on-site/off-site inspections, audits, scans, requests for information/evidence) and important entities ex post?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 32(1)–(2); Art. 33(1)–(2)", "section": "Supervision", "check_nr": 66}'::jsonb),
  ('NIS2', 'supv-67', 'Können Nachweise der Umsetzung der Cybersicherheitspolitik auf Anfrage erbracht werden, und kann die Entity benennen, wer sie erbringen würde?', 'Can evidence of implementation of cybersecurity policies be produced on request, and can the entity name who would produce it?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 32(2)(g); Art. 33(2)(f)", "section": "Supervision", "check_nr": 67}'::jsonb),
  ('NIS2', 'supv-68', 'Bildet ein Register jede Maßnahme auf das belegende Dokument ab, mit Datum und Owner, sodass die Antwort auf eine Nachweisanforderung ein Lookup und kein Projekt ist?', 'Does one register map each measure to the document that proves it, with date and owner, so a request for evidence is a lookup, not a project?', '{"coverage": "teilw", "iso_ids": ["c6-10", "a5-87"], "bsi_ids": ["PERF.2.1", "UMS.6.1"], "badge": "H", "legal_ref": "Evidenz für Art. 32(2)(g)", "section": "Supervision", "check_nr": 68}'::jsonb),
  ('NIS2', 'supv-69', 'Versteht das Leitungsorgan die Bußgeldrahmen des Art. 34 (mind. 10 Mio € / 2 % weltweiter Jahresumsatz für essential, 7 Mio € / 1,4 % für important, je höherer Wert) als gesetzliche Obergrenze bei Art.-21-/23-Verstößen, nicht als Tarif?', 'Does the management body understand the Article 34 fine ceilings (at least €10m/2% for essential, €7m/1.4% for important, whichever is higher) as the statutory maximum for Article 21/23 infringements, not a tariff?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 34(4)–(5)", "section": "Supervision", "check_nr": 69}'::jsonb),
  ('NIS2', 'supv-70', 'Ist festgehalten, dass Suspendierung von Zertifizierung/Zulassung und vorübergehendes Management-Tätigkeitsverbot nur essential entities erreichen — und nur nach erfolglosen Maßnahmen nach Art. 32(4)(a)–(d),(f) und verstrichener Nachfrist; öffentliche Verwaltung ist von beidem ausgenommen?', 'Is it recorded that suspension of certification/authorisation and a temporary management ban reach essential entities only — and only after Article 32(4)(a)–(d),(f) measures proved ineffective and the remedy deadline passed; public administration is outside both?', '{"coverage": "delta", "iso_ids": [], "bsi_ids": [], "badge": "R", "legal_ref": "Art. 32(5); vgl. Art. 33(4)", "section": "Supervision", "check_nr": 70}'::jsonb)
ON CONFLICT (framework, id) DO UPDATE
  SET req_de = EXCLUDED.req_de,
      req_en = EXCLUDED.req_en,
      meta   = public.controls.meta || EXCLUDED.meta;

